using System;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace IslandIntegrated {
 public sealed class StatusServiceResponse {public int Status;public string Body;public int? RetryAfterSeconds;}
 // Request delegate belongs to an explicitly authorized local credential owner.
 // This adapter neither retrieves a key nor accepts one, and never logs bodies.
 // Candidate only: transport must be explicitly supplied; prior denial blocks all calls.
 public sealed class MihomoDelayAdapter {
  readonly Func<string,CancellationToken,Task<StatusServiceResponse>> send;bool denied;
  public MihomoDelayAdapter(Func<string,CancellationToken,Task<StatusServiceResponse>> authorizedTransport,bool priorAccessDenied){send=authorizedTransport;denied=priorAccessDenied;}
  public async Task<int?> MeasureAsync(NetworkReadonlySnapshot route,DateTimeOffset now,CancellationToken token){
   if(denied||send==null||route==null||!route.Fresh(now)||route.MihomoState!="ok"||String.IsNullOrWhiteSpace(route.Current)||route.Current.Length>200||route.Current.Any(Char.IsControl))return null;
   string path="/proxies/"+Uri.EscapeDataString(route.Current)+"/delay?timeout=4000&url="+Uri.EscapeDataString("http://www.gstatic.com/generate_204");
   StatusServiceResponse r;try{r=await send(path,token).ConfigureAwait(false);}catch(OperationCanceledException){throw;}catch{return null;}
   if(r==null)return null;if(r.Status==403||r.Status==401){denied=true;return null;}if(r.Status!=200||r.Body==null||r.Body.Length>4096)return null;
   try{var d=new JavaScriptSerializer{MaxJsonLength=4096,RecursionLimit=4}.DeserializeObject(r.Body) as Dictionary<string,object>;object v;int n;if(d==null||!d.TryGetValue("delay",out v)||v is bool||v is string||!Int32.TryParse(Convert.ToString(v,System.Globalization.CultureInfo.InvariantCulture),out n)||n<=0||n>60000)return null;return n;}catch{return null;}
  }
 }
 public sealed class DeepSeekBalanceAdapter {
  public static readonly Uri Endpoint=new Uri("https://api.deepseek.com/user/balance");readonly Func<Uri,CancellationToken,Task<StatusServiceResponse>> request;readonly Func<DateTimeOffset> clock;readonly string currency;DateTimeOffset next=DateTimeOffset.MinValue;BalanceReadonlySnapshot current=new BalanceReadonlySnapshot();readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);
  public DeepSeekBalanceAdapter(Func<Uri,CancellationToken,Task<StatusServiceResponse>> authorizedRequest,string preferredCurrency="CNY",Func<DateTimeOffset> utc=null){request=authorizedRequest;currency=preferredCurrency;clock=utc??(()=>DateTimeOffset.UtcNow);}
  public async Task<BalanceReadonlySnapshot> ReadAsync(CancellationToken token){if(request==null)return current;if(!await gate.WaitAsync(0,token))return current;try{if(clock()<next)return current;next=clock().AddMinutes(5);StatusServiceResponse response;using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(12000);try{response=await request(Endpoint,timeout.Token).ConfigureAwait(false);}catch(OperationCanceledException){token.ThrowIfCancellationRequested();return current=new BalanceReadonlySnapshot{State="server-error"};}catch{return current=new BalanceReadonlySnapshot{State="server-error"};}}if(response==null)return current=new BalanceReadonlySnapshot{State="server-error"};if(response.RetryAfterSeconds.HasValue)next=clock().AddSeconds(Math.Max(300,response.RetryAfterSeconds.Value));if(response.Status!=200)return current=new BalanceReadonlySnapshot{State=response.Status==401||response.Status==403?"unauthorized":"server-error"};current=Parse(response.Body,currency,clock());return current;}finally{gate.Release();}}
  public static BalanceReadonlySnapshot Parse(string raw,string preferredCurrency,DateTimeOffset at){try{if(raw==null||raw.Length>16384)return new BalanceReadonlySnapshot{State="invalid"};var json=new JavaScriptSerializer{MaxJsonLength=16384,RecursionLimit=6};var d=json.DeserializeObject(raw) as Dictionary<string,object>;object rows,available;if(d==null||!d.TryGetValue("balance_infos",out rows)||!(rows is object[])||!d.TryGetValue("is_available",out available)||!(available is bool))return new BalanceReadonlySnapshot{State="invalid"};var all=((object[])rows).OfType<Dictionary<string,object>>().Where(r=>r.ContainsKey("currency")&&Convert.ToString(r["currency"])==preferredCurrency).ToArray();if(all.Length!=1)return new BalanceReadonlySnapshot{State="invalid"};var row=all[0];return BalanceReadonlySnapshot.Parse(json.Serialize(new{schema="sidebar.balance.v1",state="fresh",observedUtc=at.ToUniversalTime().ToString("o"),currency=preferredCurrency,total=row.ContainsKey("total_balance")?row["total_balance"]:null,granted=row.ContainsKey("granted_balance")?row["granted_balance"]:null,topped=row.ContainsKey("topped_up_balance")?row["topped_up_balance"]:null,available=(bool)available}));}catch{return new BalanceReadonlySnapshot{State="invalid"};}}
 }
 // Migrated GET/version -> GET/selector -> explicit PUT selection contract.
 // The transport is injected: no alternate endpoint, pipe discovery, elevation,
 // socket creation, secret lookup or production connection occurs here.
 public sealed class MihomoSelectorAdapter {
  readonly string group;readonly Func<string,string,byte[],CancellationToken,Task<StatusServiceResponse>> transport;readonly Func<DateTimeOffset> clock;readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);bool denied;public NetworkReadonlySnapshot Current {get;private set;}
  public MihomoSelectorAdapter(string exactGroup,Func<string,string,byte[],CancellationToken,Task<StatusServiceResponse>> authorizedTransport,Func<DateTimeOffset> utc=null,bool priorAccessDenied=false){denied=priorAccessDenied;if(String.IsNullOrWhiteSpace(exactGroup)||exactGroup.Length>200||exactGroup.Any(Char.IsControl))throw new ArgumentException("Invalid selector identity");group=exactGroup;transport=authorizedTransport;clock=utc??(()=>DateTimeOffset.UtcNow);Current=new NetworkReadonlySnapshot{Group=group};}
  string Path {get{return "/proxies/"+Uri.EscapeDataString(group);}}
  NetworkReadonlySnapshot Failed(string state){return Current=new NetworkReadonlySnapshot{Group=group,Timestamp=clock(),MihomoState=state};}
  async Task<StatusServiceResponse> Send(string method,string path,byte[] body,CancellationToken token){try{var result=await transport(method,path,body,token).ConfigureAwait(false);if(result!=null&&result.Status==403)denied=true;return result;}catch(UnauthorizedAccessException){denied=true;return new StatusServiceResponse{Status=403};}}
  async Task<NetworkReadonlySnapshot> ReadSelector(CancellationToken token){var response=await Send("GET",Path,null,token).ConfigureAwait(false);if(response==null||response.Status!=200)return Failed(response!=null&&response.Status==403?"access-denied":"unavailable");return Current=Parse(response.Body,group,clock());}
  public async Task<NetworkReadonlySnapshot> ReadAsync(CancellationToken token){if(transport==null)return Failed("not-connected");if(denied)return Failed("access-denied");if(!await gate.WaitAsync(0,token))return Current;try{var version=await Send("GET","/version",null,token).ConfigureAwait(false);if(version==null||version.Status!=200)return Failed(version!=null&&version.Status==403?"access-denied":"unavailable");return await ReadSelector(token).ConfigureAwait(false);}catch(OperationCanceledException){throw;}catch{return Failed("unavailable");}finally{gate.Release();}}
  public async Task<bool> SwitchAsync(string exactTarget,Func<string,bool> explicitConfirmation,CancellationToken token){if(transport==null||denied||explicitConfirmation==null||!await gate.WaitAsync(0,token))return false;try{var selection=new RouteSelection(Current);if(!selection.Select(exactTarget,clock())||!selection.NeedsChange||!explicitConfirmation(selection.Confirmation))return false;if(!Current.CanPreview(clock()))return false;var before=Current;var refreshed=await ReadSelector(token).ConfigureAwait(false);if(!refreshed.CanPreview(clock())||refreshed.Current!=before.Current||!refreshed.Choices.SequenceEqual(before.Choices))return false;var bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new{name=exactTarget}));var result=await Send("PUT",Path,bytes,token).ConfigureAwait(false);if(result==null||result.Status!=204){Failed(result!=null&&result.Status==403?"access-denied":"switch-unconfirmed");return false;}var observed=await ReadSelector(token).ConfigureAwait(false);return observed.CanPreview(clock())&&observed.Current==exactTarget;}catch(OperationCanceledException){throw;}catch{Failed("switch-unconfirmed");return false;}finally{gate.Release();}}
  public static NetworkReadonlySnapshot Parse(string raw,string exactGroup,DateTimeOffset at){try{if(raw==null||raw.Length>524288)return new NetworkReadonlySnapshot{Group=exactGroup,MihomoState="invalid"};var d=new JavaScriptSerializer{MaxJsonLength=524288,RecursionLimit=8}.DeserializeObject(raw) as Dictionary<string,object>;object type,now,choices;if(d==null||!d.TryGetValue("type",out type)||!String.Equals(type as string,"Selector",StringComparison.OrdinalIgnoreCase)||!d.TryGetValue("now",out now)||!(now is string)||!d.TryGetValue("all",out choices)||!(choices is object[]))return new NetworkReadonlySnapshot{Group=exactGroup,MihomoState="invalid"};var names=((object[])choices).OfType<string>().ToArray();if(names.Length<1||names.Length>128||names.Distinct(StringComparer.Ordinal).Count()!=names.Length||names.Any(n=>String.IsNullOrWhiteSpace(n)||n.Length>200||n.Any(Char.IsControl))||Array.IndexOf(names,(string)now)<0)return new NetworkReadonlySnapshot{Group=exactGroup,MihomoState="invalid"};return new NetworkReadonlySnapshot{Group=exactGroup,Timestamp=at,MihomoState="ok",Current=(string)now,Choices=names};}catch{return new NetworkReadonlySnapshot{Group=exactGroup,MihomoState="invalid"};}}
 }
}
